arguments.command:
python3 -c "
import openpyxl
wb = openpyxl.load_workbook('/root/test-supply.xlsx')
ws = wb['Production']
print('Production sheet first 30 rows, columns A-P:')
for row in ws.iter_rows(min_row=1, max_row=30, min_col=1, max_col=16, values_only=False):
    cells = []
    for cell in row:
        if cell.value is not None:
            cells.append(f'{cell.column_letter}{cell.row}:{cell.value}')
    if cells:
        print(cells)
"

