ws = wb['Production']
print('Production sheet rows 30-75, columns A-P:')
for row in range(30, 76):
    cells = []
    for cell in ws.iter_rows(min_row=row, max_row=row, min_col=1, max_col=16, values_only=False):
        for c in cell:
            if c.value is not None:
                cells.append(f'{c.column_letter}{c.row}:{c.value}')
    if cells:
        print(f'Row {row}:', cells)
